package com.omepikya.commandcenter.nlp;
import com.omepikya.commandcenter.core.CommandType;import java.util.Collections;import java.util.HashMap;import java.util.Map;
public class Intent {private final CommandType commandType;private final String rawCommand;private final Map<String,String> entities;private final double confidence;public Intent(CommandType commandType,String rawCommand,Map<String,String>entities,double confidence){this.commandType=commandType;this.rawCommand=rawCommand;this.entities=entities==null?new HashMap<String,String>():new HashMap<>(entities);this.confidence=confidence;}public CommandType getCommandType(){return commandType;}public String getRawCommand(){return rawCommand;}public Map<String,String> getEntities(){return Collections.unmodifiableMap(entities);}public String getEntity(String key){return entities.get(key);}public boolean hasEntity(String key){return entities.containsKey(key);}public double getConfidence(){return confidence;}public boolean isConfident(){return confidence>=.70;}}
